INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65659250', 65659250, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Penambah Daya Tahan Tubuh', 'Barang', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 444327804, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Pegawai pada Ruangan Risiko Tinggi merupakan pengadaan barang berupa suplemen/vitamin dan produk peningkat imunitas yang diperuntukkan bagi tenaga kesehatan dan pegawai yang bertugas di area dengan risiko tinggi terhadap penularan penyakit, guna menjaga kondisi kesehatan dan mendukung keberlangsungan pelayanan. Pekerjaan meliputi penyediaan produk yang memiliki izin edar resmi, distribusi sesuai jumlah dan periode yang ditetapkan, serta penyerahan dalam kondisi baik selama tahun anggaran berjalan sesuai kebijakan internal dan ketentuan yang berlaku.', 'Penyediaan suplemen/vitamin peningkat imunitas yang memiliki izin edar resmi BPOM, masa kedaluwarsa minimal 12 (dua belas) bulan sejak tanggal penerimaan, serta dikemas dalam kondisi baik dan tersegel. Produk harus memenuhi standar mutu dan keamanan pangan/obat yang berlaku, dengan komposisi dan dosis sesuai rekomendasi tenaga kesehatan. Penyedia wajib melakukan pengiriman tepat waktu sesuai jumlah kebutuhan, serta menyerahkan bukti distribusi sebagai dasar pembayaran dan pengendalian barang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2261034);
