INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65662724', 65662724, 'analyze_legacy', 'Kota Balikpapan', 'kabkota', 'UPTD-RUMAH SAKIT UMUM DAERAH', 'Belanja Modal Pengadaan Tanah BLUD', 'Barang', 'Dikecualikan', 'Kalimantan Timur, Balikpapan (Kota)', 16075400000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Kegiatan pengadaan tanah ini dilaksanakan untuk memenuhi kebutuhan lahan pembangunan sesuai ketentuan yang berlaku, termasuk Undang-Undang Nomor 2 Tahun 2012 tentang Pengadaan Tanah bagi Pembangunan untuk Kepentingan Umum. Kegiatan meliputi inventarisasi dan identifikasi tanah, penilaian oleh appraisal independen, musyawarah dan pembayaran ganti rugi kepada pihak yang berhak, serta pembayaran honor tim pengadaan tanah dan biaya lain yang timbul selama proses berlangsung, seperti biaya administrasi, pengukuran, notaris/PPAT, pajak, dan kebutuhan pendukung lainnya hingga tersedianya lahan siap digunakan.', 'Spesifikasi pengadaan tanah dalam kegiatan ini meliputi penyediaan lahan sesuai dengan lokasi, luas, dan peruntukan sebagaimana tercantum dalam dokumen perencanaan, dengan status kepemilikan yang sah dan bebas dari sengketa. Proses pengadaan dilaksanakan sesuai ketentuan peraturan perundang-undangan, termasuk Undang-Undang Nomor 2 Tahun 2012 tentang Pengadaan Tanah bagi Pembangunan untuk Kepentingan Umum, melalui tahapan inventarisasi dan identifikasi subjek serta objek tanah, penilaian oleh penilai independen (appraisal), musyawarah penetapan ganti kerugian, dan pembayaran kepada pihak yang berhak. Spesifikasi ini juga mencakup pembiayaan jasa appraisal, honorarium tim pengadaan tanah, serta seluruh biaya administratif dan teknis yang timbul hingga terselesaikannya proses pengadaan dan tersedianya lahan siap digunakan sesuai kebutuhan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2263210);
