INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65664564', 65664564, 'analyze_legacy', 'Provinsi Sulawesi Tengah', 'provinsi', 'Dinas Cipta Karya dan Sumberdaya Air', 'Penyusunan Dokumen Lingkungan Hidup D.I Tendelalos Kabupaten Toli Toli', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sulawesi Tengah, Toli-Toli (Kab.)', 100000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Lingkup Pekerjaan yang akan dilaksanakan dalam pekerjaan Penyusunan Dokumen Lingkungan Hidup D.I Tendelalos Kabupaten Toli Toli dibagi dalam beberapa item kegiatan pokok dan sub kegiatannya sebagai berikut : a. Pengumpulan Data Awal • Pengumpulan data kegiatan (lokasi, luas, jenis dan tahapan kegiatan). • Pengumpulan data lingkungan sekitar (fisik, biotik, dan sosial ekonomi). • Pengumpulan data pendukung seperti peta lokasi, foto kondisi eksisting, serta rencana tata ruang wilayah (RTRW). b. Identifikasi dan Evaluasi Dampak • Mengidentifikasi potensi dampak penting dari kegiatan terhadap lingkungan. • Menganalisis sumber dampak dari setiap tahapan kegiatan (pra konstruksi, konstruksi, dan operasional). c. Penyusunan Upaya Pengelolaan dan Pemantauan Lingkungan (UKL-UPL Sederhana) • Menyusun langkah pengelolaan lingkungan sesuai dengan jenis dampak. • Menyusun rencana pemantauan terhadap komponen lingkungan yang terkena dampak. • Menentukan indikator keberhasilan pengelolaan dan pemantauan. d. Penyusunan Dokumen SPPL • Menyusun dokumen SPPL sesuai format yang ditetapkan DLH. • Memasukkan seluruh data dan hasil identifikasi dampak serta rencana pengelolaan/pemantauan. • Melakukan konsultasi dengan pihak terkait jika diperlukan. e. Koordinasi dan Pengesahan • Melakukan koordinasi dengan instansi lingkungan hidup setempat untuk proses verifikasi. • Melengkapi persyaratan administrasi sesuai ketentuan (surat permohonan, peta lokasi, identitas usaha, dll). • Mengurus tanda terima atau pengesahan dokumen SPPL dari DLH. f. Penyerahan Dokumen Akhir • Menyerahkan dokumen SPPL final dalam bentuk cetak (hardcopy) dan softcopy. • Menyusun laporan kegiatan penyusunan SPPL lengkap dengan bukti dukung.', 'Lingkup Pekerjaan yang akan dilaksanakan dalam pekerjaan Penyusunan Dokumen Lingkungan Hidup D.I Tendelalos dibagi dalam beberapa item kegiatan pokok dan sub kegiatannya sebagai berikut : a. Pengumpulan Data Awal • Pengumpulan data kegiatan (lokasi, luas, jenis dan tahapan kegiatan). • Pengumpulan data lingkungan sekitar (fisik, biotik, dan sosial ekonomi). • Pengumpulan data pendukung seperti peta lokasi, foto kondisi eksisting, serta rencana tata ruang wilayah (RTRW). b. Identifikasi dan Evaluasi Dampak • Mengidentifikasi potensi dampak penting dari kegiatan terhadap lingkungan. • Menganalisis sumber dampak dari setiap tahapan kegiatan (pra konstruksi, konstruksi, dan operasional). c. Penyusunan Upaya Pengelolaan dan Pemantauan Lingkungan (UKL-UPL Sederhana) • Menyusun langkah pengelolaan lingkungan sesuai dengan jenis dampak. • Menyusun rencana pemantauan terhadap komponen lingkungan yang terkena dampak. • Menentukan indikator keberhasilan pengelolaan dan pemantauan. d. Penyusunan Dokumen SPPL • Menyusun dokumen SPPL sesuai format yang ditetapkan DLH. • Memasukkan seluruh data dan hasil identifikasi dampak serta rencana pengelolaan/pemantauan. • Melakukan konsultasi dengan pihak terkait jika diperlukan. e. Koordinasi dan Pengesahan • Melakukan koordinasi dengan instansi lingkungan hidup setempat untuk proses verifikasi. • Melengkapi persyaratan administrasi sesuai ketentuan (surat permohonan, peta lokasi, identitas usaha, dll). • Mengurus tanda terima atau pengesahan dokumen SPPL dari DLH. f. Penyerahan Dokumen Akhir • Menyerahkan dokumen SPPL final dalam bentuk cetak (hardcopy) dan softcopy. • Menyusun laporan kegiatan penyusunan SPPL lengkap dengan bukti dukung.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2264079);
