INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65665760', 65665760, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Subject Matter Expert (SME) Perencanaan Pemaanfaatan Data SDI Untuk Digitalisasi Perlensos dan Pemerintah Digital', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 396000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Memberikan masukan substantif terkait penyusunan Rencana Induk Pemerintahan Digital, agar arah kebijakan digital nasional berbasis pada data yang terintegrasi, andal, dan lintas sektor. Memberikan masukan dan asistensi penguatan tata kelola dan interoperabilitas data untuk mendukung Digitalisasi Program Perlindungan Sosial (Perlinsos), termasuk penyelarasan indikator, metadata, serta mekanisme integrasi antar sistem. Memberikan masukan teknis dan substantif dalam penyusunan Pedoman Pertukaran Data, guna memastikan kesesuaian dengan prinsip-prinsip SDI (standar data, metadata, interoperabilitas, dan kode referensi) serta kebutuhan pemanfaatan data antar instansi. Pelaksanaan pekerjaan dapat dilakukan secara fleksibel dengan pengaturan Work From Anywhere (WFA) dan Work From Office (WFO) sesuai kebutuhan koordinasi dan pertemuan teknis. Kehadiran fisik di kantor diperlukan untuk kegiatan-kegiatan tertentu seperti rapat koordinasi, pertemuan dengan stakeholder, dan pembahasan teknis yang memerlukan diskusi langsung. Lokasi Pelaksanaan Kegiatan: Jakarta.', 'Laporan Kinerja Triwulanan. Dokumen ringkasan capaian dan perkembangan kegiatan per termin (empat laporan selama periode Januari–Desember 2026), mencakup: Progres penyusunan Pedoman Pertukaran Data untuk Digitalisasi Perlinsos Perkembangan rekomendasi teknis pelaksanaan data exchange Kemajuan iterasi estimasi manfaat pemerintah digital Rekomendasi substantif untuk periode berikutnya b. Draft Pedoman Pertukaran Data (Data Exchange) untuk Digitalisasi Perlindungan Sosial yang memuat: Kerangka dan prinsip pertukaran data sesuai SDI Standar data dan metadata untuk program Perlinsos Mekanisme dan protokol pertukaran data lintas instansi Tata kelola dan keamanan data c. Dokumen Rekomendasi Teknis Pelaksanaan Data Exchange Perlinsos yang memuat: Skema integrasi dan arsitektur pertukaran data Protokol interoperabilitas sistem Rencana implementasi bertahap d. Dokumen Iterasi Estimasi Manfaat Pemerintah Digital berupa kajian kuantitatif yang memuat pemutakhiran perhitungan potensi manfaat implementasi pemerintahan digital, mencakup efisiensi biaya, peningkatan kualitas layanan publik, serta dampak terhadap tata kelola dan efektivitas kebijakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2264663);
