INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65629270', 65629270, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Pemeliharaan Gedung dan Bangunan', 'Pekerjaan Konstruksi', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 230718831, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Pekerjaan jasa konstruksi ringan berupa perawatan dan perbaikan rutin terhadap bagian bangunan gedung agar tetap dalam kondisi baik, aman, dan layak fungsi tanpa menambah kapasitas atau nilai aset secara signifikan. Pekerjaan meliputi perbaikan atap bocor, perbaikan dinding dan plafon, pengecatan ulang, perbaikan lantai, perawatan instalasi listrik dan sanitasi, serta pekerjaan minor lainnya sesuai kebutuhan, yang dilaksanakan selama tahun anggaran berjalan guna menjaga keberlangsungan operasional pelayanan.', 'Pelaksanaan pekerjaan perawatan dan perbaikan ringan sesuai daftar kebutuhan dan hasil identifikasi kondisi bangunan, menggunakan material yang sesuai standar mutu (SNI) dan kompatibel dengan kondisi eksisting. Pekerjaan mencakup perbaikan atap, dinding, plafon, lantai, pengecatan ulang, serta perawatan instalasi listrik dan sanitasi tanpa mengubah struktur utama bangunan. Penyedia wajib melaksanakan pekerjaan sesuai jadwal, menjaga keselamatan kerja dan kebersihan area, serta menyerahkan laporan hasil pekerjaan dan berita acara serah terima sebagai dasar pembayaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2265603);
