INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65628929', 65628929, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Modal Jaringan Gas Lainnya (Jaringan Gas Oxygen Sentral)', 'Barang', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 435572000, 'January 2026', 'BLUD', 1, 1, '2 Paket', 'Pengadaan dan pembangunan instalasi jaringan distribusi gas medis oksigen terpusat yang bersifat aset tetap untuk mendukung pelayanan kesehatan sesuai standar keselamatan dan teknis yang berlaku. Pekerjaan meliputi perencanaan teknis, pengadaan material dan peralatan, pemasangan pipa distribusi, panel kontrol, outlet point, sistem pengaman, serta uji tekanan dan uji fungsi hingga sistem beroperasi normal dan siap digunakan pada tahun anggaran berjalan.', 'Penyediaan dan pemasangan instalasi jaringan gas medis oksigen menggunakan material dan komponen khusus gas medis (pipa tembaga medical grade, valve, manifold, pressure regulator, alarm system, outlet point) yang memenuhi standar keselamatan dan teknis yang berlaku. Pekerjaan mencakup instalasi sesuai gambar kerja, pengujian tekanan (pressure test), uji kebocoran, uji fungsi sistem, serta penyediaan dokumen as built drawing, sertifikat kelayakan, dan berita acara serah terima sebagai dasar pencatatan aset tetap dan operasional pelayanan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2265817);
