INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65628937', 65628937, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Modal Bangunan Gedung', 'Pekerjaan Konstruksi', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 400000000, 'January 2026', 'BLUD', 1, 1, '1 Unit', 'Pekerjaan konstruksi berupa perbaikan, peningkatan, dan penataan ulang ruang CDSC guna memenuhi standar fungsi, keselamatan, dan kenyamanan pelayanan. Pekerjaan meliputi pembongkaran bagian eksisting yang diperlukan, pekerjaan struktur ringan/non-struktur, perbaikan dinding, lantai, plafon, pengecatan, instalasi listrik dan utilitas pendukung, serta finishing hingga ruang dalam kondisi layak, aman, dan siap digunakan pada tahun anggaran berjalan sesuai gambar dan spesifikasi teknis yang ditetapkan.', 'Meliputi pelaksanaan pekerjaan konstruksi sesuai gambar kerja dan RAB yang disetujui, menggunakan material baru dan berkualitas baik (standar SNI), mencakup pekerjaan pembongkaran terbatas, perbaikan struktur/non-struktur, pekerjaan dinding, lantai, plafon, pengecatan, instalasi listrik dan utilitas pendukung, serta pekerjaan finishing hingga memenuhi standar keselamatan, kesehatan kerja, dan kelayakan fungsi ruang. Penyedia wajib melaksanakan pekerjaan sesuai jadwal, menjaga keamanan area kerja, serta menyerahkan laporan progres, dokumentasi, dan berita acara serah terima sebagai dasar pencatatan aset tetap.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2265830);
