INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65628836', 65628836, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Modal Mebeuler', 'Barang', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 100000000, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Pengadaan barang berupa pembelian dan pengadaan perabot/furnitur kantor seperti meja, kursi, lemari, rak arsip, meja rapat, dan perlengkapan sejenis lainnya yang bersifat aset tetap dan digunakan untuk mendukung operasional pelayanan dan administrasi instansi. Pekerjaan meliputi pengadaan barang sesuai spesifikasi teknis, pengiriman ke lokasi yang ditetapkan, pemasangan/perakitan apabila diperlukan, serta penyerahan barang dalam kondisi baik dan siap digunakan pada tahun anggaran berjalan.', 'Penyediaan perabot/furnitur baru dan bukan rekondisi, sesuai daftar kebutuhan dan spesifikasi teknis (ukuran, bahan, warna, dan desain) yang ditetapkan, dengan material berkualitas baik dan konstruksi kuat untuk penggunaan jangka panjang. Barang harus dalam kondisi utuh, bebas cacat, dilengkapi perakitan/pemasangan apabila diperlukan, serta diserahkan lengkap dengan garansi pabrik/penyedia dan berita acara serah terima sebagai dasar pencatatan aset tetap.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2267206);
