INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65628910', 65628910, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Modal Alat Rumah Tangga Lainnya (Home Use)', 'Barang', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 35000000, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Pengadaan barang berupa pembelian dan penyediaan peralatan penunjang operasional seperti dispenser, mesin cuci, vacuum cleaner, kipas angin, water heater, dan peralatan rumah tangga sejenis lainnya yang bersifat aset tetap untuk mendukung kebersihan, kenyamanan, dan kelancaran pelayanan instansi. Pekerjaan meliputi penyediaan unit baru sesuai spesifikasi teknis, pengiriman ke lokasi yang ditetapkan, pemasangan dan uji fungsi apabila diperlukan, serta penyerahan barang dalam kondisi baik dan siap digunakan pada tahun anggaran berjalan.', 'Penyediaan peralatan baru dan bukan rekondisi sesuai daftar kebutuhan dan spesifikasi teknis (kapasitas, daya listrik, material, dan fitur keselamatan), dengan kualitas baik dan sesuai standar penggunaan operasional. Penyedia wajib melakukan pengiriman, instalasi dan uji fungsi apabila diperlukan, menjamin barang dalam kondisi normal dan siap pakai, memberikan garansi resmi pabrik/penyedia, serta menyerahkan dokumen serah terima sebagai dasar pencatatan aset tetap.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2268446);
