INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65629483', 65629483, 'analyze_legacy', 'Kab. Kebumen', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Pemeliharaan Berkala Jalan Kabekelan - Lembupurwo', 'Pekerjaan Konstruksi', 'E-Purchasing', 'Jawa Tengah, Kebumen (Kab.)', 2000000000, 'February 2026', 'APBD', 1, 1, '2000000000 Rupiah', 'PEMBUATAN PRODUK PADA https://katalog.inaproc.id/ KATEGORI JASA SISTEM MANAJEMEN KESELAMATAN KONSTRUKSI (SMKK), BIDANG BINA MARGA dan BIDANG UMUM: KATEGORI PRODUK TINGKAT I JASA SISTEM MANAJEMEN KESELAMATAN KONSTRUKSI (SMKK) : Kategori Produk Tingkat II Penerapan SMKK : Kategori Produk Tingkat III Komponen 1 Penyiapan dokumen penerapan SMKK : - Kategori Produk Tingkat IV Pembuatan dokumen SMKK (RKK dan RMPK); Kategori Produk Tingkat III Komponen 2 Sosialisasi, promosi dan pelatihan : - Kategori Produk Tingkat IV Induksi Keselamatan Konstruksi (Safety Induction); Kategori Produk Tingkat III Komponen 3 Alat Pelindung Kerja dan Alat Pelindung Diri : - Kategori Produk Tingkat IV Rompi keselamatan (Safety Vest); Kategori Produk Tingkat III Komponen 5 Personel Keselamatan Konstruksi : - Kategori Produk Tingkat IV Petugas Keselamatan Konstruksi, Petugas K3 Konstruksi; Kategori Produk Tingkat III Komponen 6 Fasilitas sarana, prasarana, dan alat kesehatan : - Kategori Produk Tingkat IV Peralatan P3K A; Kategori Produk Tingkat III Komponen 7 Rambu dan Perlengkapan lalu lintas yang diperlukan atau manajemen lalu lintas: - Kategori Produk Tingkat IV Rambu Informasi; Kategori Produk Tingkat III Komponen 9 Kegiatan dan peralatan terkait Pengendalian Risiko Keselamatan Konstruksi : - Kategori Produk Tingkat IV Bendera K3; KATEGORI PRODUK TINGKAT I JASA BIDANG BINA MARGA/BIDANG UMUM : KATEGORI PRODUK TINGKAT II DIVISI 1 UMUM/ U.1 Persiapan : Kategori Produk Tingkat III 1.2 Mobilisasi/ U.1.3 Mobilisasi dan Demobilisasi : - Kategori Produk Tingkat IV Mobilisasi/Kebutuhan Lainnya; KATEGORI PRODUK TINGKAT II DIVISI 3 PEKERJAAN TANAH DAN GEOSINTETIK : Kategori Produk Tingkat III 3.1 Galian : - Kategori Produk Tingkat IV Galian Biasa; Kategori Produk Tingkat III 3.3 Penyiapan Badan Jalan: - Kategori Produk Tingkat IV Penyiapan Badan Jalan; KATEGORI PRODUK TINGKAT II DIVISI 5 PERKERASAN BERBUTIR DAN PERKERASAN BETON SEMEN : Kategori Produk Tingkat III 5.1 Lapis Pondasi Agregat : - Kategori Produk Tingkat IV Lapis Pondasi Agregat Kelas A; KATEGORI PRODUK TINGKAT II DIVISI 6 PERKERASAN ASPAL Kategori Produk Tingkat III 6.3 Campuran Beraspal Panas : - Kategori Produk Tingkat IV Laston Lapis Antara (AC-BC); Kategori Produk Tingkat III 6.1 Lapis Resap Pengikat dan Lapis Perekat : - Kategori Produk Tingkat IV Lapis Resap Pengikat - Aspal Cair/Emulsi; KATEGORI PRODUK TINGKAT II DIVISI 10 PEKERJAAN PEMELIHARAAN : Kategori Produk Tingkat III 10.1 Pemeliharaan Jalan : - Kategori Produk Tingkat IV Perbaikan Lapis Fondasi Agregat Kelas A; - Kategori Produk Tingkat IV Perbaikan Campuran Aspal Panas; DETAIL KEBUTUHAN PEKERJAAN DAPAT DI UNDUH MELALUI LINK BERIKUT >> https://tinyurl.com/2d2mgysh', 'Spesifikasi Umum 2025 untuk Pekerjaan Konstruksi Jalan dan Jembatan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2268774);
