INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65629285', 65629285, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Pemeliharaan Kendaraan Dinas dan Ambulance', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Banjar (Kota)', 41291400, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Perawatan dan perbaikan rutin maupun berkala untuk menjaga kondisi kendaraan tetap laik jalan, aman, dan siap operasional dalam mendukung pelayanan dan kegiatan kedinasan. Pekerjaan meliputi servis berkala, penggantian suku cadang aus, perbaikan sistem mesin, kelistrikan, rem, AC, ban, serta perawatan khusus peralatan medis pada ambulans sesuai standar keselamatan dan teknis yang berlaku, yang dilaksanakan selama tahun anggaran berjalan guna menjamin kelangsungan operasional pelayanan.', 'Pelaksanaan servis berkala dan perbaikan sesuai standar pabrikan, termasuk penggantian oli dan filter, tune up mesin, perbaikan sistem rem, suspensi, kelistrikan, AC, ban, serta penggantian suku cadang dengan komponen baru dan berkualitas setara OEM. Untuk ambulans, pekerjaan juga mencakup pemeriksaan dan perawatan peralatan medis terpasang serta sistem kelistrikan tambahan. Penyedia wajib menjamin kendaraan dalam kondisi laik jalan dan aman digunakan, memberikan laporan hasil servis, serta menyertakan bukti penggantian suku cadang sebagai dasar pembayaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2268776);
