INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65628848', 65628848, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Modal Alat Pendingin', 'Barang', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 135000000, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Pengadaan barang berupa pembelian dan pemasangan peralatan pendingin seperti AC split/standing, chiller, freezer, lemari pendingin, atau perangkat sejenis lainnya yang bersifat aset tetap untuk mendukung operasional pelayanan dan penyimpanan sesuai standar kebutuhan instansi. Pekerjaan meliputi penyediaan unit baru sesuai spesifikasi teknis, pengiriman, instalasi dan uji fungsi di lokasi yang ditetapkan, serta penyerahan barang dalam kondisi baik, siap digunakan, dan tercatat sebagai aset pada tahun anggaran berjalan.', 'Penyediaan unit baru dan bukan rekondisi sesuai kapasitas dan spesifikasi teknis yang ditetapkan (daya listrik, kapasitas pendinginan/volume, jenis refrigeran ramah lingkungan, serta efisiensi energi), dilengkapi komponen instalasi standar pabrikan dan fitur pengaman yang memadai. Penyedia wajib melakukan pengiriman, pemasangan, uji fungsi hingga alat beroperasi normal, memberikan garansi resmi pabrik/penyedia, serta menyerahkan dokumen manual dan berita acara serah terima sebagai dasar pencatatan aset tetap.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2269751);
