INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65629388', 65629388, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Pemeliharaan Instalasi Air Kotor (limbah) dan Sanitasi', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Banjar (Kota)', 153984806, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Pekerjaan jasa lainnya berupa perawatan dan perbaikan sistem pengelolaan air limbah dan sarana sanitasi agar tetap berfungsi optimal, aman, dan memenuhi standar kesehatan lingkungan. Pekerjaan meliputi pemeriksaan dan pembersihan jaringan pipa limbah, bak kontrol, grease trap, septic tank, saluran drainase, serta perbaikan kebocoran atau penyumbatan, yang dilaksanakan selama tahun anggaran berjalan guna menjamin kelancaran sistem pembuangan dan mencegah pencemaran lingkungan serta gangguan operasional pelayanan.', 'Pelaksanaan pemeriksaan, pembersihan, penyedotan, dan perbaikan jaringan pipa limbah, bak kontrol, grease trap, septic tank, saluran drainase, serta komponen pendukung lainnya menggunakan peralatan dan material sesuai standar teknis dan kesehatan lingkungan. Pekerjaan mencakup penanganan penyumbatan, kebocoran, dan kerusakan ringan hingga sedang, serta uji fungsi untuk memastikan sistem pembuangan limbah berjalan normal dan aman. Penyedia wajib menyerahkan laporan hasil pekerjaan dan dokumentasi sebagai dasar pembayaran dan pengendalian sarana.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2269949);
